text:
Here's your water tracker: tap + for each glass and it counts toward 8. It saves on this device and starts fresh each day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Segoe UI, sans-serif; text-align: center; margin: 0; padding: 24px; background: #f0f7fb; color: #1b3a4b; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  #date { font-size: 13px; color: #5a7684; margin-bottom: 16px; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; max-width: 320px; margin: 0 auto 16px; }
  .g { width: 56px; height: 72px; border: 3px solid #4a9fc8; border-radius: 6px 6px 14px 14px; background: #fff; position: relative; overflow: hidden; }
  .g.full::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 85%; background: #5bc0eb; }
  #count { font-size: 40px; font-weight: 600; }
  #msg { height: 22px; margin: 4px 0 16px; color: #2e7d4f; }
  button { font-size: 18px; padding: 10px 22px; margin: 0 6px; border: none; border-radius: 8px; background: #4a9fc8; color: #fff; cursor: pointer; }
  button.alt { background: #cfdde5; color: #1b3a4b; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="glasses"></div>
  <div id="count"></div>
  <div id="msg"></div>
  <button onclick="change(1)">+ Glass</button>
  <button class="alt" onclick="change(-1)">- Undo</button>
  <button class="alt" onclick="reset()">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date();
  var key = "water-" + today.toISOString().slice(0, 10);
  var n = 0;
  try { n = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch (e) {}
  document.getElementById("date").textContent =
    today.toLocaleDateString("en-IN", { weekday: "short", day: "numeric", month: "short" });
  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }
  function change(d) { n = Math.max(0, n + d); save(); draw(); }
  function reset() { n = 0; save(); draw(); }
  function draw() {
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var g = document.createElement("div");
      g.className = "g" + (i < n ? " full" : "");
      box.appendChild(g);
    }
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Nicely done!" : (GOAL - n) + " more to go";
  }
  draw();
</script>
</body>
</html>
```
